from pathlib import Path
root=Path(__file__).resolve().parent
h=(root/'플레이.html').read_text()
test=r'''<script>
(async()=>{await document.fonts.ready;const checks=[];const wait=ms=>new Promise(r=>setTimeout(r,ms));const click=s=>{const e=document.querySelector(s);if(!e)throw Error('missing '+s);if(typeof e.click==='function')e.click();else e.dispatchEvent(new MouseEvent('click',{bubbles:true}))};const report=(name,ok)=>{checks.push({name,ok:Boolean(ok)});if(!ok)throw Error(name)};function place(m,w,x,y){click('[data-model="'+m+'"]');click('[data-cell="'+x+','+y+'"]');click('[data-word="'+w+'"]')}
function valid(loc='안'){place('y_s','집',0,0);place('y_ns',loc,0,1);place('y_ne','주민',0,2);place('y_twin','나',1,1);place('b_give','주다',1,2);place('y_w','열쇠',2,2)}
try{Puzzle13.reset();if(Puzzle13.getState().sound)click('#sound');report('initial chat hidden',document.querySelector('#conversation').hidden);click('#npc-outside');report('world npc opens chat',!document.querySelector('#conversation').hidden);report('outside speech has four pieces',document.querySelectorAll('#speech svg text').length===4);click('#npc-inside');report('inside speech has three pieces',document.querySelectorAll('#speech svg text').length===3);report('both heard',Puzzle13.getState().heard.inside&&Puzzle13.getState().heard.outside);click('[data-recall="outside"]');report('recall retains shape',document.querySelectorAll('#speech svg text').length===4);click('#close-chat');report('close chat',document.querySelector('#conversation').hidden);click('#npc-inside');
// make incomplete and correct through real controls
place('y_twin','나',1,1);click('#speak');report('incomplete not complete',!Puzzle13.getState().world.complete);click('#clear');report('clear empty',Puzzle13.getState().pieces.length===0);click('#undo');report('undo restores',Puzzle13.getState().pieces.length===1);click('#clear');
valid('밖');const originalNa=Puzzle13.getState().pieces.find(p=>p.word==='나');document.querySelector('[data-piece="'+originalNa.id+'"]').dispatchEvent(new KeyboardEvent('keydown',{key:'Enter',bubbles:true}));report('select does not overwrite glyph',Puzzle13.getState().pieces.find(p=>p.id===originalNa.id).word==='나');click('#speak');report('wrong target tracked',Puzzle13.getState().attempts.at(-1).code==='wrong_target');report('busy locks repeat submit',document.querySelector('#speak').disabled);await wait(1550);report('wrong target returns key',Puzzle13.getState().world.keyOwner==='player'&&!Puzzle13.getState().world.complete);report('wrong target keeps pieces',Puzzle13.getState().pieces.length===6);report('failure unlocks',!document.querySelector('#speak').disabled);
// move with pointer then keyboard undo, preserving piece ID and glyph
click('[data-model="y_s"]');const state=Puzzle13.getState(),piece=state.pieces.find(p=>p.word==='열쇠');let el=document.querySelector('[data-piece="'+piece.id+'"]');let r=el.getBoundingClientRect();const start={x:r.x+r.width/2,y:r.y+r.height/2};const u=74*document.querySelector('#board').getScreenCTM().a;
el.dispatchEvent(new PointerEvent('pointerdown',{bubbles:true,button:0,pointerId:7,clientX:start.x,clientY:start.y}));window.dispatchEvent(new PointerEvent('pointermove',{bubbles:true,pointerId:7,clientX:start.x+u,clientY:start.y}));window.dispatchEvent(new PointerEvent('pointerup',{bubbles:true,pointerId:7,clientX:start.x+u,clientY:start.y}));report('pointer drag moves one cell',Puzzle13.getState().pieces.find(p=>p.id===piece.id).x===3);click('#undo');report('undo move',Puzzle13.getState().pieces.find(p=>p.id===piece.id).x===2);
// direct keyboard select then move
el=document.querySelector('[data-piece="'+piece.id+'"]');el.dispatchEvent(new KeyboardEvent('keydown',{key:'ArrowRight',bubbles:true}));report('keyboard move',Puzzle13.getState().pieces.find(p=>p.id===piece.id).x===3);window.dispatchEvent(new KeyboardEvent('keydown',{key:'z',ctrlKey:true,bubbles:true}));report('keyboard undo',Puzzle13.getState().pieces.find(p=>p.id===piece.id).x===2);
// click grid to select inside word, then edit only that glyph
click('[data-model="y_s"]');click('[data-cell="0,1"]');click('[data-word="안"]');report('word replacement',Puzzle13.getState().pieces.find(p=>p.x===0&&p.y===1).word==='안');report('correct graph parsed',Puzzle13.analyze().ok);click('[data-recall="outside"]');click('#speak');report('last speaker outside does not choose recipient',Puzzle13.getState().attempts.at(-1).code==='complete');await wait(1200);report('complete owns key inside',Puzzle13.getState().world.complete&&Puzzle13.getState().world.keyOwner==='inside');report('complete panel shown',!document.querySelector('#complete-panel').hidden);report('no horizontal overflow',document.documentElement.scrollWidth<=innerWidth);
// restart cancels state and permits skip-observation success
click('#again');report('restart fresh',Puzzle13.getState().pieces.length===0&&!Puzzle13.getState().world.complete&&!Puzzle13.getState().heard.inside);click('#npc-outside');valid('안');click('#speak');await wait(1200);report('no forced observation',Puzzle13.getState().world.complete&&!Puzzle13.getState().heard.inside);
// leave a reviewable assembled state, completion final screenshot is separate
click('#again');click('#npc-outside');click('#npc-inside');valid('안');report('last ready state',Puzzle13.analyze().ok);report('final overflow',document.documentElement.scrollWidth<=innerWidth);
}catch(e){checks.push({name:'exception: '+e.message,ok:false})}
if(checks.every(x=>x.ok)&&location.hash==='#complete'){click('#speak');await wait(1400)}const out=document.createElement('pre');out.id='verification';out.hidden=true;out.textContent=JSON.stringify({width:innerWidth,passed:checks.every(x=>x.ok),checks});document.body.appendChild(out);
})();</script>'''
# don't leave test progress in actual user storage
h=h.replace("const STORAGE='grad.puzzle13.v1'","const STORAGE='grad.puzzle13.v1.browsertest'")
Path('/mnt/c/Users/cj307/AppData/Local/Temp/puzzle13-test.html').write_text(h.replace('</body>',test+'</body>'))
